# ---- begin include rewrite/lib/eb_moe.py ----
# Engine B moe adapter (campaign 2026-10-26-decode-first-rewrite, W3): canary, per-bucket selector, state copy check and
# summary for muse_moe_w4a16's kernel_fn (global expert ids, the bank's local range). Needs eb_core.py and ea_core.py.

EB_TAG = "[engineB]"

EB_EXT_NAME = "okc_campaign_engine_b_v2"

EB_START_DEADLINE_S = 180.0   # the build (~40-60 s, cannot be interrupted) starts only before this many s into prepare()

EB_CANARY_DEADLINE_S = 245.0  # the canary starts only before this

EB_GATE_DEADLINE_S = 256.0    # the selector starts only before this

EB_COPY_DEADLINE_S = 266.0    # the two-state copy check starts only before this

EB_BUDGET_S = {"canary": 70.0, "gate": 78.0, "copy": 84.0}   # also: no phase past this many s after Engine B's start

EB_COPY_TOL = 1e-4            # graph replay on a state copy vs eager kernel_fn (Engine B sums in a fixed order)

EB_BUCKETS = ((128, "B128", "128 <= T <= 255"), (256, "B256", "256 <= T <= 512"))

EB_JUDGE_TOUCHED = {128: 23, 256: 25}   # mean touched local experts per call at verify_16 / verify_32 (forensics 1)

EB_GATE_KINDS = ("judge", "zipf", "random")

# (T, routing): the scored shapes, both bucket edges, the judge's test shapes (257, 128 skewed) and forced extremes.
EB_CANARY_CASES = ((128, "judge"), (128, "zipf"), (128, "random"), (128, "skewed"), (128, "one-hot"),
                   (128, "all-local"), (128, "zero-local"), (129, "skewed-4hot"), (255, "judge"), (256, "judge"),
                   (256, "one-hot"), (256, "zipf"), (257, "random"), (257, "one-hot"), (384, "skewed"),
                   (512, "judge"), (512, "one-hot"), (512, "all-local"))


def _eb_forward(x, topk_ids, topk_weights, bank, state, cell, trace=None):
    """moe adapter: this GPU's expert block through Engine B on `cell` (ids are global, the bank's range is local)."""
    return _eb_forward_core(state["eb"], x, topk_ids, topk_weights, bank["start"], bank["count"],
                            state["post_norm_w"], cell, trace)


def _eb_cfg(bank, tokens, hidden):
    return {"bs": tokens, "d_hidden": hidden, "d_expert": bank["size_n"], "n_experts": N_EXPERTS,
            "local_start": bank["start"], "local_count": bank["count"], "top_k": TOP_K, "sharding": "ep8"}


def _eb_judge_draw(tokens, gen, start, count):
    """Of 6 reference-style draws (_eb_ref_ids, dist normal), the one whose touched local experts are nearest the
    judge's mean at this T (EB_JUDGE_TOUCHED). CPU int32 [tokens, 8]."""
    target = EB_JUDGE_TOUCHED.get(128 if tokens < EB_B256_MIN_T else 256, 23)
    best = None
    for _ in range(6):
        ids = _eb_ref_ids(tokens, gen, "normal", start, count)
        loc = ids.long().flatten() - start
        touched = int(torch.unique(loc[(loc >= 0) & (loc < count)]).numel())
        if best is None or abs(touched - target) < best[0]:
            best = (abs(touched - target), ids)
    return best[1]


def _eb_routing(kind, tokens, gen, local_set, device):
    """topk_ids [tokens, 8] int32 on `device` of one named routing (prepare only)."""
    start, count = local_set[0], len(local_set)
    remote = [e for e in range(N_EXPERTS) if e not in set(local_set)]

    def pick_remote(k):
        return [remote[i] for i in torch.randperm(len(remote), generator=gen)[:k].tolist()]

    if kind == "judge":
        ids = _eb_judge_draw(tokens, gen, start, count)
    elif kind == "skewed":
        ids = _eb_ref_ids(tokens, gen, "skewed", start, count)
    elif kind == "zipf":
        ids = _wg_zipf_ids(tokens, 0.9, gen, local_set)
    elif kind in ("random", "skewed-4hot"):
        ids = torch.tensor(_wg_routing(kind, tokens, gen, local_set, remote), dtype=torch.int32)
    elif kind == "one-hot":  # every token on one local expert: runs of NMAX of a single expert
        hot = local_set[3 % count]
        ids = torch.tensor([[hot] + pick_remote(TOP_K - 1) for _ in range(tokens)], dtype=torch.int32)
    elif kind == "all-local":  # every route local, every local expert touched, uniform
        ids = torch.tensor([[local_set[(TOP_K * t + j) % count] for j in range(TOP_K)] for t in range(tokens)],
                           dtype=torch.int32)
    elif kind == "zero-local":
        ids = torch.tensor([pick_remote(TOP_K) for _ in range(tokens)], dtype=torch.int32)
    else:
        raise ValueError(f"unknown routing {kind}")
    return ids.to(device).contiguous()


def _eb_late(phase, deadline, t_prepare, t0):
    """Reason text if `phase` must not start (past its absolute deadline or Engine B's own budget), else ''."""
    el, own = time.perf_counter() - t_prepare, time.perf_counter() - t0
    if el > deadline:
        return f"{phase} skipped: deadline ({el:.1f} s into prepare > {deadline:.0f} s)"
    if own > EB_BUDGET_S[phase]:
        return f"{phase} skipped: Engine B budget ({own:.1f} s since its start > {EB_BUDGET_S[phase]:.0f} s)"
    return ""


def _eb_canary(weights, bank, state, device, t_prepare, t0, cells):
    """Untimed, eager, synced, every bucket on master meanwhile. For every case of EB_CANARY_CASES and every built cell:
    error word 0, the GEMM launch marker, tickets back at 0, finite output, rel-L2 and worst row against the fp32
    reference built with the case's own routing (_combo_ref_fp32) within half the judge's bounds (_rt_check), no
    worse than 2x master's own error, and exact zeros without local routes. A cell's first miss turns it off.
    Returns ({cell: bool}, [lines])."""
    eb = state["eb"]
    start, count = bank["start"], bank["count"]
    hidden, inter = weights["w2"].shape[1], bank["size_n"]
    local_set = list(range(start, start + count))
    ok = {c: True for c in cells}
    worst = {c: 0.0 for c in cells}
    lines, first = [], True
    gen = torch.Generator().manual_seed(20261030)
    for tokens, kind in EB_CANARY_CASES:
        late = _eb_late("gate", EB_GATE_DEADLINE_S, t_prepare, t0)  # never run the canary into the gate's limits
        if late:
            for c in cells:
                ok[c] = False
            lines.append(f"{EB_TAG} canary T={tokens} {kind}: {late} -> every cell off")
            break
        if not any(ok.values()):
            break
        ids = _eb_routing(kind, tokens, gen, local_set, device)
        x = torch.randn((tokens, hidden), generator=gen).to(torch.bfloat16).to(device)
        tw = torch.rand((tokens, TOP_K), generator=gen)
        tw = (tw / tw.sum(-1, keepdim=True)).to(device)
        data = {"hidden_states": x, "topk_ids": ids, "topk_weights": tw, "config": _eb_cfg(bank, tokens, hidden)}
        master = kernel_fn(data, state).float()
        ref = _combo_ref_fp32(weights, bank, state, x, ids, tw)
        torch.cuda.synchronize()
        m_rel = _combo_rel(master, ref)
        touched, maxr, nloc, _, _ = _eb_active_bytes(ids, start, count, inter, hidden)
        for c in cells:
            if not ok[c]:
                continue
            eb["err"].zero_()
            eb["tk13"].zero_()  # the cells share the tickets: a failed cell must not poison the next one's fix-ups
            eb["tk2"].zero_()
            try:
                if first:
                    print(f"{EB_TAG} first launch: cell {EB_CELL_KEY[c]} T={tokens} {kind} (each launch named, synced)", flush=True)
                tr = _rt_tracer(EB_TAG, f"{EB_CELL_KEY[c]} T={tokens} {kind}") if first else None
                out = _eb_forward(x, ids, tw, bank, state, c, tr)
                torch.cuda.synchronize()
                first = False
                errw, marker = int(eb["err"][0]), int(eb["err"][1])
                tk_left = int(eb["tk13"].abs().sum()) + int(eb["tk2"].abs().sum())
                good, rel, row, text = _rt_check(out, ref)
                good = (good and errw == 0 and marker == EB_MAGIC and tk_left == 0
                        and rel <= 2.0 * max(m_rel, 2e-3))
                if nloc == 0:
                    good = good and bool((out.float() == 0).all())
                worst[c] = max(worst[c], rel)
                msg = (f"{text}, master {m_rel:.3g}, error word {errw} ({EB_ERR_TEXT.get(errw, '?')}), marker "
                       f"0x{marker & 0xffffffff:x}, tickets left {tk_left}")
            except Exception as e:
                good, msg = False, f"raised {type(e).__name__}: {str(e)[:200]}"
            if not good:
                ok[c] = False
                lines.append(f"{EB_TAG} canary FAIL {EB_CELL_KEY[c]} T={tokens} {kind} (touched {touched}, max routes {maxr}, "
                             f"local routes {nloc}): {msg}")
                print(lines[-1], flush=True)
        del data, master, ref
    lines.append(f"{EB_TAG} canary: {len(EB_CANARY_CASES)} cases (T 128..512; judge, zipf, random, skewed, one-hot, "
                 f"all-local, zero-local, 4-hot): "
                 + ", ".join(f"{EB_CELL_KEY[c]} {'clean' if ok[c] else 'FAIL'} (worst rel-L2 vs fp32 {worst[c]:.3g})"
                             for c in cells))
    return ok, lines


def _eb_kernel_rates(weights, bank, state, device, cells, diag_ok):
    """Kernel-only graph times (read flush, empty-graph baseline subtracted) on the judge-like routing at T = 128 and 256:
    eb_prep, each clean cell's w13 and w2, and the w13 diagnostics: cell m without the MMA (ring + code loads +
    dequant), cell m without the dequant (ring + B fragments + mma.sync), cell w without the dequant (ring + wgmma), the
    ring alone (stages streamed and released, nothing computed); TB/s on the touched experts' bytes, and the part of cell
    m's w13 time that each explains (>= 90 % names the limiter). Diagnostic lines only."""
    eb = state["eb"]
    ext = eb["ext"]
    start, count, inter = bank["start"], bank["count"], bank["size_n"]
    hidden = weights["w2"].shape[1]
    local_set = list(range(start, start + count))
    gen = torch.Generator().manual_seed(20261031)
    lines = []
    for tokens in (128, 256):
        ids = _eb_routing("judge", tokens, gen, local_set, device)
        touched, maxr, nloc, b13, b2 = _eb_active_bytes(ids, start, count, inter, hidden)
        routes = tokens * TOP_K
        x = torch.randn((tokens, hidden), generator=gen).to(torch.bfloat16).to(device)
        xs = torch.zeros((routes, hidden), dtype=torch.bfloat16, device=device)
        hs = torch.zeros((routes, inter), dtype=torch.bfloat16, device=device)
        y = torch.empty((routes, hidden), dtype=torch.bfloat16, device=device)
        sr = torch.zeros((routes,), dtype=torch.int32, device=device)
        lid = torch.empty((tokens, TOP_K), dtype=torch.int32, device=device)

        def gemm(cell, which, diag):
            if which == 0:
                return lambda: ext.eb_gemm(cell, 0, diag, xs, ids, eb["w13q"], eb["gs13"], sr, hs, eb["ws13"], eb["tk13"],
                                           eb["err"], tokens, start, count, eb["grid"][cell], eb["costs"][cell], 0, 0)
            return lambda: ext.eb_gemm(cell, 1, diag, hs, ids, eb["w2q"], eb["gs2"], sr, y, eb["ws2"], eb["tk2"],
                                       eb["err"], tokens, start, count, eb["grid"][cell], eb["costs"][cell], 0, 0)

        gp, _ = _rt_graph(lambda: ext.eb_prep(ids, x, xs, sr, lid, tokens, start, count, 0))
        graphs = {"prep": gp}
        for c in cells:
            k = EB_CELL_KEY[c]
            graphs[f"{k} w13"], _ = _rt_graph(gemm(c, 0, 0))
            graphs[f"{k} w2"], _ = _rt_graph(gemm(c, 1, 0))
        for (k, d), name in ((("m", 1), "m no-MMA"), (("m", 2), "m no-dequant"), (("w", 2), "w no-dequant"),
                             (("m", 3), "ring only")):
            cell = 2 if k == "m" else 1
            if diag_ok.get((k, d), False) and cell in eb["grid"]:
                graphs[name], _ = _rt_graph(gemm(cell, 0, d))
        r = _rt_time(graphs, device, reps=21, rounds=1)[0]
        med = {k: _rt_stats(v)[0] for k, v in r.items() if k != "__baseline_us__"}

        def tb(us, b):
            return b / max(us, 1e-3) / 1e6
        parts = [f"prep {med['prep']:.2f} us"]
        for c in cells:
            k = EB_CELL_KEY[c]
            t13, t2 = med[f"{k} w13"], med[f"{k} w2"]
            parts.append(f"{k}: w13 {t13:.1f} us ({tb(t13, b13):.2f} TB/s), w2 {t2:.1f} us ({tb(t2, b2):.2f} TB/s), "
                         f"sum {t13 + t2:.1f} us")
        lines.append(f"{EB_TAG} kernel-only T={tokens} judge-like (touched {touched}, max routes {maxr}, local routes "
                     f"{nloc}, {(b13 + b2) / 1e6:.0f} MB): " + "; ".join(parts))
        dparts = [f"{n} {med[n]:.1f} us ({tb(med[n], b13):.2f} TB/s)" for n in
                  ("m no-MMA", "m no-dequant", "w no-dequant", "ring only") if n in med]
        verdict = "n/a"
        if "m w13" in med and all(n in med for n in ("m no-MMA", "m no-dequant", "ring only")):
            full = max(med["m w13"], 1e-3)
            share = {n: med[n] / full for n in ("ring only", "m no-dequant", "m no-MMA")}
            if share["ring only"] >= 0.9:
                verdict = "RING (stream + barriers): the consumer is not the bound"
            elif share["m no-dequant"] >= 0.9:
                verdict = "MMA PATH (mma.sync + B fragments)"
            elif share["m no-MMA"] >= 0.9:
                verdict = "DEQUANT (code loads + integer dequant)"
            else:
                verdict = "OVERLAP (no single part >= 90 % of the full kernel)"
            verdict += " [" + ", ".join(f"{n} {v:.2f}" for n, v in share.items()) + " of m w13]"
        if dparts:
            lines.append(f"{EB_TAG} diag T={tokens} w13: " + "; ".join(dparts) + f" -> limiter {verdict}")
        del graphs, gp
    return lines


def _eb_gate(weights, bank, state, device, cells, t_prepare, t0):
    """Per bucket (T = 128 for B128, T = 256 for B256): kernel_fn with Engine B on each clean cell vs off (master's own
    choice for the bucket: its wgmma path or Marlin), cold-L2 graph replays on a judge-like, a zipf and a random routing,
    two interleaved rounds (_rt_select: every round on every routing >= 1.03x, or >= 1.02x with a tight IQR); the best
    qualifying cell wins. Returns ({bucket: cell or 0}, [lines])."""
    eb = state["eb"]
    start, count = bank["start"], bank["count"]
    hidden = weights["w2"].shape[1]
    local_set = list(range(start, start + count))
    gen = torch.Generator().manual_seed(20261032)
    won, lines = {}, []
    for tokens, name, _ in EB_BUCKETS:
        won[tokens] = 0
        late = _eb_late("gate", EB_GATE_DEADLINE_S, t_prepare, t0)
        if late:
            lines.append(f"{EB_TAG} gate {name}: {late}, master kept")
            continue
        per = {}
        for kind in EB_GATE_KINDS:
            tw = torch.rand((tokens, TOP_K), generator=gen)
            data = {"hidden_states": torch.randn((tokens, hidden), generator=gen).to(torch.bfloat16).to(device),
                    "topk_ids": _eb_routing(kind, tokens, gen, local_set, device),
                    "topk_weights": (tw / tw.sum(-1, keepdim=True)).to(device),
                    "config": _eb_cfg(bank, tokens, hidden)}
            graphs = {}
            eb["cell"][tokens] = 0
            graphs["master"], _ = _rt_graph(lambda: kernel_fn(data, state))
            for c in cells:
                eb["cell"][tokens] = c
                graphs[EB_CELL_KEY[c]], _ = _rt_graph(lambda: kernel_fn(data, state))
            eb["cell"][tokens] = 0
            per[f"{name} T={tokens} {kind}"] = _rt_time(graphs, device)
            del graphs
        win, worst, glines = _rt_select(per, "master", [EB_CELL_KEY[c] for c in cells])
        lines.extend(f"{EB_TAG} gate {ln}" for ln in glines)
        won[tokens] = next((c for c in cells if EB_CELL_KEY[c] == win), 0) if win else 0
        lines.append(f"{EB_TAG} gate {name}: worst ratio master/cell "
                     + ", ".join(f"{EB_CELL_KEY[c]} {worst[EB_CELL_KEY[c]]:.3f}" for c in cells)
                     + f" -> {('ENGINE B ' + EB_CELL_KEY[won[tokens]]) if won[tokens] else 'master'}")
    return won, lines


def _eb_copy_check(weights, bank, state, device):
    """The judge copies the prepared state (cloned tensors) and rotates the copies: for every ON bucket, graphs of
    kernel_fn on this state and on a tensor-cloning copy, alternating replays with refilled inputs, each against eager
    kernel_fn on this state. A miss turns every bucket back to master. Returns a line."""
    eb = state["eb"]
    start, count = bank["start"], bank["count"]
    hidden = weights["w2"].shape[1]
    local_set = list(range(start, start + count))
    ts = [t for t, _, _ in EB_BUCKETS if eb["cell"].get(t, 0)]
    if not ts:
        return f"{EB_TAG} copy check: no bucket is ON"
    other = _wg_copy_tree(state)
    gen = torch.Generator().manual_seed(20261033)
    fails, n = [], 0
    for tokens in ts:
        cfg = _eb_cfg(bank, tokens, hidden)
        per = []
        for st in (state, other):
            data = {"hidden_states": torch.zeros((tokens, hidden), dtype=torch.bfloat16, device=device),
                    "topk_ids": torch.full((tokens, TOP_K), start, dtype=torch.int32, device=device),
                    "topk_weights": torch.full((tokens, TOP_K), 1.0 / TOP_K, dtype=torch.float32, device=device),
                    "config": cfg}
            graph, out = _rt_graph(lambda data=data, st=st: kernel_fn(data, st))
            per.append((data, graph, out))
        for k in range(4):
            ids = _eb_routing("judge" if k % 2 == 0 else "zipf", tokens, gen, local_set, device)
            x = torch.randn((tokens, hidden), generator=gen).to(torch.bfloat16).to(device)
            tw = torch.rand((tokens, TOP_K), generator=gen).to(device)
            for data, _, _ in per:
                data["hidden_states"].copy_(x)
                data["topk_ids"].copy_(ids)
                data["topk_weights"].copy_(tw)
            for _, graph, _ in (per if k % 2 == 0 else per[::-1]):
                graph.replay()
            torch.cuda.synchronize()
            ref = kernel_fn({"hidden_states": x, "topk_ids": ids, "topk_weights": tw, "config": cfg}, state).float()
            for i, (_, _, out) in enumerate(per):
                n += 1
                rel = _combo_rel(out.float(), ref)
                if not rel <= EB_COPY_TOL:
                    fails.append(f"T={tokens} state {'AB'[i]} refill {k}: rel-L2 vs eager {rel:.3g}")
        del per
        torch.cuda.synchronize()
    errw = int(eb["err"][0]) + int(other["eb"]["err"][0])
    if errw:
        fails.append(f"error word set ({errw})")
    if fails:
        for t, _, _ in EB_BUCKETS:
            eb["cell"][t] = 0
    del other
    gc.collect()
    torch.cuda.empty_cache()
    return (f"{EB_TAG} copy check: {n} replays on two states, T {ts}: "
            + ("PASS" if not fails else f"FAIL -> master for every bucket: {fails[0]}"))


def _eb_setup(weights, state, device, t_prepare):
    """Untimed, after master's prepare and Engine A's. Never raises: any miss leaves state['eb']['cell'][bucket] 0
    (master's path). Detail lines print as they happen; the return value is the compact summary prepare() prints last,
    PATH CHOSEN lines at the end."""
    lines = []

    def say(s):
        lines.append(s)
        print(s, flush=True)

    state["eb"] = {"cell": {t: 0 for t, _, _ in EB_BUCKETS}}
    t0 = time.perf_counter()
    built = []
    try:
        bank = state["banks"][(0, 32)]
        el = time.perf_counter() - t_prepare
        if el > EB_START_DEADLINE_S:
            raise RuntimeError(f"skipped: deadline (start at {el:.1f} s > {EB_START_DEADLINE_S:.0f} s)")
        start, count, inter = bank["start"], bank["count"], bank["size_n"]
        hidden = weights["w2"].shape[1]
        if (inter != 4096 or hidden != 4096 or count > 32 or bank["expert_map"] is None
                or tuple(torch.cuda.get_device_capability(device)) != (9, 0)):
            raise RuntimeError(f"unsupported: I={inter} H={hidden} count={count} "
                               f"capability {tuple(torch.cuda.get_device_capability(device))}")
        if not _ea_scales_ok(weights, start, count):
            raise RuntimeError("a block-scale byte is outside [0x08, 0x7E]: the exact integer dequant does not apply")
        ext, err_text, dt, cells, ilines = _eb_build_ext(EB_TAG, EB_EXT_NAME)
        if ext is None:
            raise RuntimeError(f"build failed: {err_text[-400:]}")
        for ln in ilines:
            say(ln)
        built = [c for c in EB_CELLS if cells[c]["ok"]]
        for c in EB_CELLS:
            if not cells[c]["ok"]:
                say(f"{EB_TAG} cell {EB_CELL_KEY[c]} off: {cells[c]['why']}")
        if not built:
            raise RuntimeError("no usable cell")
        late = _eb_late("canary", EB_CANARY_DEADLINE_S, t_prepare, t0)
        if late:
            raise RuntimeError(late)
        state["eb"]["inter"] = inter
        wtext, rep_s = _eb_weights(state, weights, start, count)
        sms = int(torch.cuda.get_device_properties(device).multi_processor_count)
        state["eb"].update({"ext": ext, **_eb_buffers(device, sms, {c: cells[c] for c in built})})
        say(f"{EB_TAG} weights: own 128-k copy {wtext} ({rep_s:.1f} s)"
            + "; " + "; ".join(f"{EB_CELL_TEXT[c]} grid {state['eb']['grid'][c]}" for c in built)
            + f"; build {dt:.1f} s")
        ok, clines = _eb_canary(weights, bank, state, device, t_prepare, t0, built)
        lines.extend(clines[:-1])  # the FAIL lines were printed as they happened
        say(clines[-1])
        for key in ("tk13", "tk2", "err"):  # a failed cell may have left a ticket or the error word set
            state["eb"][key].zero_()
        clean = [c for c in built if ok.get(c, False)]
        if not clean:
            raise RuntimeError("canary failed for every cell")
        try:  # diagnostic only: a miss here must not turn Engine B off
            for ln in _eb_kernel_rates(weights, bank, state, device, clean, cells.get("diag_ok", {})):
                say(ln)
        except Exception as e:
            lines.append(f"{EB_TAG} kernel-only rates raised {type(e).__name__}: {str(e)[:200]}")
        won, glines = _eb_gate(weights, bank, state, device, clean, t_prepare, t0)
        for ln in glines:
            if "round" in ln:
                print(ln, flush=True)
            else:
                lines.append(ln)
        for t, _, _ in EB_BUCKETS:
            state["eb"]["cell"][t] = int(won.get(t, 0))
        if any(state["eb"]["cell"].values()):
            late = _eb_late("copy", EB_COPY_DEADLINE_S, t_prepare, t0)
            if late:
                for t, _, _ in EB_BUCKETS:
                    state["eb"]["cell"][t] = 0
                lines.append(f"{EB_TAG} copy check: {late} -> master for every bucket")
            else:
                lines.append(_eb_copy_check(weights, bank, state, device))
    except Exception as e:  # prepare only: never raises, every bucket stays on master
        for t, _, _ in EB_BUCKETS:
            state["eb"]["cell"][t] = 0
        lines.append(f"{EB_TAG} {type(e).__name__}: {str(e)[:400]}")
    try:
        torch.cuda.synchronize()
    except Exception as e:
        lines.append(f"{EB_TAG} final sync raised {type(e).__name__}: {str(e)[:200]}")
    cell = state["eb"]["cell"]
    tail = [f"{EB_TAG} ===== ENGINE B SUMMARY ({time.perf_counter() - t0:.1f} s; module {EB_EXT_NAME}; prepare at "
            f"{time.perf_counter() - t_prepare:.1f} s) ====="]
    tail.extend(ln for ln in lines if "kernel-only" in ln or ("gate B" in ln and "round" not in ln)
                or "copy check" in ln or "canary" in ln or "weights:" in ln or "Error" in ln or "skipped" in ln
                or " off:" in ln or "diag T=" in ln
                or ("attrs ok" in ln and "no-" not in ln and "ring" not in ln and "prep" not in ln))
    for t, name, rng_text in EB_BUCKETS:
        tail.append(f"{EB_TAG} PATH CHOSEN {name} ({rng_text}) = "
                    + (f"ENGINE B {EB_CELL_TEXT[cell[t]]}" if cell[t] else "MASTER"))
    return tail
# ---- end include rewrite/lib/eb_moe.py ----
# ---- campaign moe hybrid (T = 256): decode's hot/cold hybrid on moe's bank (needs Engine A v3) ----
CAMPAIGN_HYBRID = True      # hot experts on Marlin at |H|, cold experts on Engine A v3 (per-T flag from prepare)
# ---- begin include rewrite/lib/hotcold_moe.py ----
# Campaign moe hybrid (branch campaign/moe-hybrid): rewrite/lib/hotcold_decode.py's judge-proven hybrid expert block,
# ported to muse_moe_w4a16 at T = 256 exactly (verify_32). One Triton launch (_hm_align_kernel, decode's
# _hc_align_kernel renamed) shifts the GLOBAL routing ids by the bank's start (a [1] int32 device scalar,
# state['hm']['ls']), counts the routes per local expert on the device and writes the full local ids, both classes'
# (sorted_ids, block_experts, n_padded) and the cold-only local ids; every size comes from the shape. A HOT expert
# (more than HM_HOT_ROWS local routes) runs moe_wna16_marlin_gemm at block |H| (w13, silu_and_mul over every row, w2
# into cache3); then the COLD experts run Engine A v3 (state['ea'], built by _ea_setup) on the cold ids into cache3's
# cold rows (after the hot w2: cache3 aliases cache1); then master's post-norm at T >= 32
# (fused_post_expert_norm_weighted_sum, state['norm_w']) once over every local row. A positive H is decode's plain
# hot/cold (both classes on Marlin, the cold one at block 16). Graph-capturable; kernel_fn branches on the shape and
# state['hm']['on'][T] only. prepare(): align build, canary (fp32 reference, half the judge's bounds, poisoned caches),
# kernel_fn graph gate against whatever kernel_fn runs today at T (the wgmma path), a hooked-layer check and the
# two-state copy check. Never raises from prepare: every miss keeps master.

HM_TAG = "[hybrid-moe]"
HM_TOKENS = (128, 256)           # exact T the flag covers (verify_16 / verify_32); every other T keeps its path
HM_HOT_ROWS = 16                 # an expert with more local routes than this is HOT
HM_COLD_BSM = 16                 # the cold class's Marlin block (plain hot/cold only)
HM_BSMS = (-16, -8, -32, -48, 32, 48)  # H < 0: hybrid (hot on Marlin at |H| or, for the HM_WG_HOT codes, on the wgmma
                                        # path; cold on Engine A); H > 0: plain hot/cold
HM_WG_H = -16                    # expert-bandwidth: the hybrid with hot experts on the wgmma path (aligned at its block
                                 # 16; it reads a hot expert's weights once per chunk of <= 128 routes), cold on Engine A
HM_COLD_SLOTS = (HM_HOT_ROWS + HM_COLD_BSM - 1) // HM_COLD_BSM * HM_COLD_BSM  # a cold expert pads to at most this
HM_JUNK = 100.0                  # prepare()-only poison in cache13 / cache3 before the GEMMs
HM_COPY_TOL = 1e-3               # graph replay on a state copy vs eager kernel_fn (rel L2)
HM_START_DEADLINE_S = 250.0      # nothing starts after this many s into prepare()
HM_GATE_DEADLINE_S = 255.0       # no canary routing / gate starts after this
HM_COPY_DEADLINE_S = 262.0       # no layer check / copy check starts after this (then master)


HM_WG_HOT = {-16: 16, -8: 8}  # expert-bandwidth: wgmma-hot codes -> the hot threshold (routes); -8 also takes the
                              # 9..16-route experts Engine A runs as two-tile passes (its slowest case, ladder-2)


def _hm_hot_rows(bsm_hot):
    """The route count above which an expert is HOT under H: a wgmma-hot code's own threshold, else HM_HOT_ROWS."""
    return HM_WG_HOT.get(bsm_hot, HM_HOT_ROWS)


def _hm_hot_block(bsm_hot):
    """The hot class's block size under H: WG_BSM for a wgmma-hot code, else |H|."""
    return WG_BSM if bsm_hot in HM_WG_HOT else abs(bsm_hot)


def _hm_caps(n, bsm_hot, count):
    """(cold capacity, cold blocks, hot capacity, hot blocks) from the route count n = T * 8, H and the bank's count."""
    h = _hm_hot_block(bsm_hot)
    cap_c = count * HM_COLD_SLOTS
    cap_h = n + count * (h - 1)
    return cap_c, cap_c // HM_COLD_BSM, cap_h, triton.cdiv(cap_h, h)


@triton.jit(do_not_specialize=["n", "cap_c", "nb_c", "cap_h", "nb_h"])
def _hm_align_kernel(ids_ptr, ls_ptr, local_ids_ptr, sc_ptr, bc_ptr, nc_ptr, sh_ptr, bh_ptr, nh_ptr,
                     n, cap_c, nb_c, cap_h, nb_h, cold_ids_ptr, HOT: tl.constexpr, CHUNK: tl.constexpr,
                     PAD: tl.constexpr, BLK: tl.constexpr, BSM_C: tl.constexpr, BSM_H: tl.constexpr,
                     NUM_E: tl.constexpr, N_GLOBAL: tl.constexpr, COLD_IDS: tl.constexpr):
    """decode's _hc_align_kernel, unchanged: grid (NUM_E + 1,). The raw routing ids are shifted by the device scalar
    ls ((id - ls) mod N_GLOBAL; local experts are 0..NUM_E-1, the rest remote). Every program counts all local experts;
    an expert with more than HOT routes is HOT, the others COLD; each class gets its own padded segments in expert
    order. Program e < NUM_E places expert e's routes (ascending), its padding slots (sentinel n) and its block_experts
    entries; program NUM_E writes the full local ids (-1 remote), the cold ids (COLD_IDS), the sentinel past each
    class's used length, -1 past each class's used blocks, and both n_padded. Store sets are disjoint."""
    pid = tl.program_id(0)
    offs0 = tl.arange(0, CHUNK)
    experts = tl.arange(0, NUM_E)
    ls = tl.load(ls_ptr).to(tl.int32)

    counts = tl.zeros([NUM_E], dtype=tl.int32)
    for c in range(0, n, CHUNK):
        offs = c + offs0
        mask = offs < n
        ids = tl.load(ids_ptr + offs, mask=mask, other=0).to(tl.int32)
        local = ((ids - ls) % N_GLOBAL + N_GLOBAL) % N_GLOBAL
        local = tl.where(mask & (local < NUM_E), local, -1)
        counts += tl.sum((local[:, None] == experts[None, :]).to(tl.int32), axis=0)
    hot = counts > HOT
    cnt_c = tl.where(hot, 0, counts)
    cnt_h = tl.where(hot, counts, 0)
    pad_c = (cnt_c + BSM_C - 1) // BSM_C * BSM_C
    pad_h = (cnt_h + BSM_H - 1) // BSM_H * BSM_H
    start_c = tl.cumsum(pad_c, axis=0) - pad_c
    start_h = tl.cumsum(pad_h, axis=0) - pad_h
    total_c = tl.sum(pad_c, axis=0)
    total_h = tl.sum(pad_h, axis=0)

    if pid < NUM_E:
        sel = experts == pid
        my_c = tl.sum(tl.where(sel, cnt_c, 0), axis=0)
        my_h = tl.sum(tl.where(sel, cnt_h, 0), axis=0)
        my_pc = tl.sum(tl.where(sel, pad_c, 0), axis=0)
        my_ph = tl.sum(tl.where(sel, pad_h, 0), axis=0)
        my_sc = tl.sum(tl.where(sel, start_c, 0), axis=0)
        my_sh = tl.sum(tl.where(sel, start_h, 0), axis=0)
        in_c = my_c > 0
        in_h = my_h > 0
        base_c = my_sc
        base_h = my_sh
        for c in range(0, n, CHUNK):
            offs = c + offs0
            mask = offs < n
            ids = tl.load(ids_ptr + offs, mask=mask, other=0).to(tl.int32)
            local = ((ids - ls) % N_GLOBAL + N_GLOBAL) % N_GLOBAL
            match = (mask & (local == pid)).to(tl.int32)
            rank = tl.cumsum(match, axis=0) - 1
            tl.store(sc_ptr + base_c + rank, offs, mask=(match > 0) & in_c)
            tl.store(sh_ptr + base_h + rank, offs, mask=(match > 0) & in_h)
            k = tl.sum(match, axis=0)
            base_c += k
            base_h += k
        j = tl.arange(0, PAD)
        tl.store(sc_ptr + my_sc + my_c + j, tl.zeros([PAD], dtype=tl.int32) + n, mask=j < my_pc - my_c)
        tl.store(sh_ptr + my_sh + my_h + j, tl.zeros([PAD], dtype=tl.int32) + n, mask=j < my_ph - my_h)
        kb0 = tl.arange(0, BLK)
        b0c = my_sc // BSM_C
        nbc = my_pc // BSM_C
        for kk in range(0, nbc, BLK):
            kb = kk + kb0
            tl.store(bc_ptr + b0c + kb, tl.zeros([BLK], dtype=tl.int32) + pid, mask=kb < nbc)
        b0h = my_sh // BSM_H
        nbh = my_ph // BSM_H
        for kk in range(0, nbh, BLK):
            kb = kk + kb0
            tl.store(bh_ptr + b0h + kb, tl.zeros([BLK], dtype=tl.int32) + pid, mask=kb < nbh)
    else:
        for c in range(0, n, CHUNK):
            offs = c + offs0
            mask = offs < n
            ids = tl.load(ids_ptr + offs, mask=mask, other=0).to(tl.int32)
            local = ((ids - ls) % N_GLOBAL + N_GLOBAL) % N_GLOBAL
            local = tl.where(local < NUM_E, local, -1)
            tl.store(local_ids_ptr + offs, local, mask=mask)
            if COLD_IDS:  # hybrid: the local ids with the hot experts' routes made remote, for Engine A v3
                is_hot = tl.sum(((local[:, None] == experts[None, :]) & hot[None, :]).to(tl.int32), axis=1) > 0
                tl.store(cold_ids_ptr + offs, tl.where(is_hot, -1, local), mask=mask)
        for s in range(0, cap_c, CHUNK):
            slots = s + offs0
            tl.store(sc_ptr + slots, tl.zeros([CHUNK], dtype=tl.int32) + n, mask=(slots >= total_c) & (slots < cap_c))
        for s in range(0, cap_h, CHUNK):
            slots = s + offs0
            tl.store(sh_ptr + slots, tl.zeros([CHUNK], dtype=tl.int32) + n, mask=(slots >= total_h) & (slots < cap_h))
        kb0 = tl.arange(0, BLK)
        used_c = total_c // BSM_C
        for kk in range(0, nb_c, BLK):
            kb = kk + kb0
            tl.store(bc_ptr + kb, tl.zeros([BLK], dtype=tl.int32) - 1, mask=(kb >= used_c) & (kb < nb_c))
        used_h = total_h // BSM_H
        for kk in range(0, nb_h, BLK):
            kb = kk + kb0
            tl.store(bh_ptr + kb, tl.zeros([BLK], dtype=tl.int32) - 1, mask=(kb >= used_h) & (kb < nb_h))
        tl.store(nc_ptr, total_c)
        tl.store(nh_ptr, total_h)


def _hm_align(topk_ids, ls, bsm_hot, count):
    """One launch: (local_ids [T, 8] int32, (cold sorted_ids, block_experts, n_padded, hot sorted_ids, block_experts,
    n_padded[, cold ids for H < 0])) from the GLOBAL routing ids and the device scalar ls (the bank's start)."""
    topk_ids = topk_ids.contiguous()
    device = topk_ids.device
    n = topk_ids.numel()
    cap_c, nb_c, cap_h, nb_h = _hm_caps(n, bsm_hot, count)
    local_ids = torch.empty(topk_ids.shape, dtype=torch.int32, device=device)
    sc = torch.empty((cap_c,), dtype=torch.int32, device=device)
    bc = torch.empty((nb_c,), dtype=torch.int32, device=device)
    nc = torch.empty((1,), dtype=torch.int32, device=device)
    sh = torch.empty((cap_h,), dtype=torch.int32, device=device)
    bh = torch.empty((nb_h,), dtype=torch.int32, device=device)
    nh = torch.empty((1,), dtype=torch.int32, device=device)
    hyb, h = bsm_hot < 0, _hm_hot_block(bsm_hot)
    cold_ids = torch.empty(topk_ids.shape, dtype=torch.int32, device=device) if hyb else local_ids
    _hm_align_kernel[(count + 1,)](
        topk_ids, ls, local_ids, sc, bc, nc, sh, bh, nh, n, cap_c, nb_c, cap_h, nb_h, cold_ids,
        HOT=_hm_hot_rows(bsm_hot), CHUNK=ALIGN_PAR_CHUNK, PAD=triton.next_power_of_2(max(HM_COLD_BSM, h)),
        BLK=ALIGN_PAR_BLK, BSM_C=HM_COLD_BSM, BSM_H=h, NUM_E=count, N_GLOBAL=N_EXPERTS, COLD_IDS=hyb,
        num_warps=ALIGN_PAR_WARPS)
    return local_ids, ((sc, bc, nc, sh, bh, nh, cold_ids) if hyb else (sc, bc, nc, sh, bh, nh))


def _hm_experts(x, local_ids, tw, align, bank, state, bsm_hot, fill=None):
    """decode's _hc_experts with moe's bank, workspace and post-norm: hot experts on Marlin at |H| (plain H > 0: cold
    experts on Marlin at HM_COLD_BSM too), silu_and_mul over every row, the hybrid's cold experts on Engine A v3 after
    the hot w2, then master's fused post-norm (T >= 32) over the full local ids. tw is fp32 contiguous. fill
    (prepare()-only): poison cache13 before w13 and cache3 before w2, so a route row nothing writes cannot pass."""
    num_tokens, size_k = x.shape
    size_n = bank["size_n"]
    count = bank["count"]
    gemm1_n = 2 * size_n
    hybrid = bsm_hot < 0
    if hybrid:
        sc, bc, nc, sh, bh, nh, cold_ids = align
        classes = ((sh, bh, nh, -bsm_hot),)
    else:
        sc, bc, nc, sh, bh, nh = align
        classes = ((sc, bc, nc, HM_COLD_BSM), (sh, bh, nh, bsm_hot))
    if bsm_hot in HM_WG_HOT:
        # Hot experts on the wgmma path (its gather, w13 + silu into h_sorted, w2 into cache3 at the route index) with
        # the hot class aligned at its block 16; the cold experts follow on Engine A below, into their own rows.
        routes = num_tokens * TOP_K
        wb = state["wg_banks"][(bank["start"], count)]
        cache3 = torch.empty((routes, size_k), device=x.device, dtype=x.dtype)
        if fill is not None:
            cache3.fill_(fill)
        state["wg_ext"].wg_gather(x, sh, bh, nh, routes, count, state["wg_xs"])
        _wg_gemm(state, 0, wb["q13"], wb["gs13"], sh, bh, nh, routes, size_n // 64, size_k, state["wg_hs"])
        _wg_gemm(state, 1, wb["q2"], wb["gs2"], sh, bh, nh, routes, size_k // 128, size_n, cache3)
        classes = ()
    cache2 = torch.empty((num_tokens * TOP_K, size_n), device=x.device, dtype=x.dtype)
    if classes:
        cache13 = torch.empty((num_tokens * TOP_K * max(gemm1_n, size_k),), device=x.device, dtype=x.dtype)
        cache1 = cache13[: num_tokens * TOP_K * gemm1_n].view(-1, gemm1_n)
        cache3 = cache13[: num_tokens * TOP_K * size_k].view(-1, size_k)
    common = dict(mul_topk_weights=False, is_ep=True, b_q_type=scalar_types.float4_e2m1f, is_k_full=True,
                  use_atomic_add=False, use_fp32_reduce=True, is_zp_float=False)
    ws = state["workspace"]
    if fill is not None and classes:
        cache13.fill_(fill)
    for sorted_ids, block_experts, n_padded, bsm in classes:
        moe_wna16_marlin_gemm(
            x, cache1, bank["w13"], None, bank["w13_s"], bank["w13_gs"], None, None, None, ws,
            sorted_ids, block_experts, n_padded, tw, moe_block_size=bsm, top_k=TOP_K,
            size_m=num_tokens, size_n=gemm1_n, size_k=size_k, **common)
    if classes:
        silu_and_mul(cache1.view(-1, gemm1_n), cache2, expert_ids=local_ids.view(-1), expert_step=1)
    if fill is not None and classes:
        cache3.fill_(fill)
    for sorted_ids, block_experts, n_padded, bsm in classes:
        moe_wna16_marlin_gemm(
            cache2, cache3, bank["w2"], None, bank["w2_s"], bank["w2_gs"], None, None, None, ws,
            sorted_ids, block_experts, n_padded, tw, moe_block_size=bsm, top_k=1,
            size_m=num_tokens * TOP_K, size_n=size_k, size_k=size_n, **common)
    if hybrid:
        # Cold experts (<= HM_HOT_ROWS routes) through Engine A v3 into cache3's cold rows: after the hot w2 because
        # cache3 aliases cache1; the hot rows are final and v3 writes only its own routes. The cold ids are local
        # (0..count-1, -1 remote or hot), so v3 runs with start 0.
        ea = state["ea"]
        ext = ea["ext"]
        h3 = torch.empty((num_tokens * TOP_K, size_n), device=x.device, dtype=torch.bfloat16)
        lid3 = torch.empty((num_tokens, TOP_K), device=x.device, dtype=torch.int32)
        k13, k2 = (ext.ea4_w13, ext.ea4_w2) if state["hm"].get("cold") == "v4" else (ext.ea3_w13, ext.ea3_w2)
        cb = state["hm"].get("cold_bits", {}).get(num_tokens, 0)  # v4c's cost bits (0: count split)
        k13(x, cold_ids, ea["w13r"], ea["gs13"], h3, lid3, ea["ws13"], ea["tk13"], ea["err"], num_tokens, 0,
            count, ea["grid"], ea["dq"], cb)
        k2(h3, cold_ids, ea["w2r"], ea["gs2"], cache3, ea["ws2"], ea["tk2"], ea["err"], num_tokens, 0,
           count, ea["grid"], ea["dq"], ea["pdl"] | cb)
    y = cache3.view(num_tokens, TOP_K, size_k)
    return fused_post_expert_norm_weighted_sum(
        y, tw, norm_weight=state["norm_w"], eps=POST_NORM_EPS, weight_first=True, slot_expert_ids=local_ids)


def _hm_forward(x, topk_ids, topk_weights, bank, state, bsm_hot, fill=None):
    """kernel_fn's hybrid branch: out [T, H] bf16 from the GLOBAL ids (shifted on the device by state['hm']['ls'])."""
    tw = topk_weights.to(torch.float32).contiguous()
    local_ids, align = _hm_align(topk_ids, state["hm"]["ls"], bsm_hot, bank["count"])
    return _hm_experts(x, local_ids, tw, align, bank, state, bsm_hot, fill)


# ---- prepare()-only: checks, gate, summary -----------------------------------------------------------------------------
def _hm_align_ref(ids_cpu, ls, bsm_hot, count):
    """_hm_align's exact outputs on the host: (local ids [T, 8], cold (sorted, blocks, n_padded), hot (...))."""
    flat = [int(v) for v in ids_cpu.reshape(-1).tolist()]
    n = len(flat)
    cap_c, nb_c, cap_h, nb_h = _hm_caps(n, bsm_hot, count)
    thr = _hm_hot_rows(bsm_hot)
    h = _hm_hot_block(bsm_hot)
    local = []
    routes = {e: [] for e in range(count)}
    for i, v in enumerate(flat):
        e = (v - ls) % N_EXPERTS
        e = e if e < count else -1
        local.append(e)
        if e >= 0:
            routes[e].append(i)

    def build(want_hot, bsm, cap, nb):
        srt, blk = [], []
        for e in range(count):
            r = routes[e]
            if not r or (len(r) > thr) != want_hot:
                continue
            padded = -(-len(r) // bsm) * bsm
            srt += r + [n] * (padded - len(r))
            blk += [e] * (padded // bsm)
        total = len(srt)
        return srt + [n] * (cap - total), blk + [-1] * (nb - len(blk)), total

    return (torch.tensor(local, dtype=torch.int32).view(ids_cpu.shape), build(False, HM_COLD_BSM, cap_c, nb_c),
            build(True, h, cap_h, nb_h))


def _hm_align_cmp(ids_cpu, ls, bsm_hot, count, local_ids, align):
    """Exact comparison of the device align with _hm_align_ref. Returns None or the first mismatch."""
    ref_l, ref_c, ref_h = _hm_align_ref(ids_cpu, ls, bsm_hot, count)
    if not torch.equal(local_ids.cpu(), ref_l):
        return "local ids differ"
    if len(align) == 7:  # hybrid: the cold ids are the local ids with every hot expert's routes made remote
        flat = ref_l.reshape(-1).tolist()
        hot = {e for e in set(flat) if e >= 0 and flat.count(e) > _hm_hot_rows(bsm_hot)}
        want = torch.tensor([-1 if e in hot else e for e in flat], dtype=torch.int32).view(ref_l.shape)
        if not torch.equal(align[6].cpu(), want):
            return "cold ids differ"
    for name, (srt, blk, total), (s_d, b_d, n_d) in (("cold", ref_c, align[0:3]), ("hot", ref_h, align[3:6])):
        if int(n_d.cpu()[0]) != total:
            return f"{name} n_padded {int(n_d.cpu()[0])} != {total}"
        if not torch.equal(s_d.cpu(), torch.tensor(srt, dtype=torch.int32)):
            return f"{name} sorted_ids differ"
        if not torch.equal(b_d.cpu(), torch.tensor(blk, dtype=torch.int32)):
            return f"{name} block_experts differ"
    return None


def _hm_local(ids, start, count):
    """Local ids [T, 8] (-1 remote) of GLOBAL ids, on the ids' device."""
    loc = (ids.long() - start) % N_EXPERTS
    return torch.where(loc < count, loc, torch.full_like(loc, -1))


def _hm_counts_text(local_ids, count):
    """Routing shape of local ids [T, 8] (-1 remote): local routes, distinct experts, the hot class, 16-row blocks."""
    flat = local_ids.reshape(-1).long()
    counts = torch.bincount(flat[flat >= 0], minlength=count).tolist()
    hot = [c for c in counts if c > HM_HOT_ROWS]
    return (f"local routes {sum(counts)}, distinct {sum(1 for c in counts if c)}, hot experts {len(hot)} "
            f"({sum(hot)} rows, max {max(counts)}), 16-row blocks {sum(-(-c // HM_COLD_BSM) for c in counts)}")


def _hm_data(bank, x, ids, tw):
    return {"hidden_states": x, "topk_ids": ids, "topk_weights": tw, "config": _ea_cfg(bank, x.shape[0], x.shape[1])}


def _hm_warm(device, state, count):
    """Compile _hm_align_kernel for every H (one variant each; n / caps are runtime) and run it once. Returns
    ({H: None or the failure}, lines)."""
    lines, bad = [], {}
    for h in HM_BSMS:
        t0 = time.perf_counter()
        try:
            _hm_align(torch.zeros((HM_TOKENS[0], TOP_K), dtype=torch.int32, device=device), state["hm"]["ls"], h, count)
            torch.cuda.synchronize()
            bad[h] = None
            lines.append(f"{HM_TAG} align kernel H={h}: compiled + ran in {time.perf_counter() - t0:.2f} s")
        except Exception as e:  # prepare only: a Triton build error; this H stays off
            bad[h] = f"align build {type(e).__name__}"
            lines.append(f"{HM_TAG} align kernel H={h} raised {type(e).__name__} after {time.perf_counter() - t0:.2f} s: "
                         f"{str(e)[:300]}")
    return bad, lines


def _hm_canary(weights, bank, state, device, t_prepare, built):
    """Untimed, eager, synced, per T in HM_TOKENS on every _ea_routings kind and every H: the align exactly against
    its host reference, then _hm_forward with poisoned caches against the fp32 reference (_combo_ref_fp32 on the same
    ids): _rt_check (half the judge's bounds), <= 2x master's own error (kernel_fn today), Engine A error word 0, exact
    zeros for tokens without a local route when master's are. The first launch per H is traced. Returns
    ({(T, H): bool}, {(T, H): why}, [lines])."""
    ea = state["ea"]
    start, count = bank["start"], bank["count"]
    hidden = weights["w2"].shape[1]
    local_set = list(range(start, start + count))
    ok = {(t, h): built.get(h) is None for t in HM_TOKENS for h in HM_BSMS}
    why = {(t, h): built[h] for t in HM_TOKENS for h in HM_BSMS if built.get(h) is not None}
    worst, m_worst, lines = {h: 0.0 for h in HM_BSMS}, 0.0, []
    first = {h: True for h in HM_BSMS}
    gen = torch.Generator().manual_seed(20261101)
    for tokens in HM_TOKENS:
        for label, ids in _ea_routings(tokens, gen, local_set, device):
            if time.perf_counter() - t_prepare > HM_GATE_DEADLINE_S:
                for h in HM_BSMS:
                    if ok[(tokens, h)]:
                        ok[(tokens, h)], why[(tokens, h)] = False, "canary skipped: deadline"
                lines.append(f"{HM_TAG} canary T={tokens} {label}: skipped: deadline")
                break
            x = torch.randn((tokens, hidden), generator=gen).to(torch.bfloat16).to(device)
            tw = torch.rand((tokens, TOP_K), generator=gen)
            tw = (tw / tw.sum(-1, keepdim=True)).to(device).contiguous()
            master = kernel_fn(_hm_data(bank, x, ids, tw), state).float()
            ref = _combo_ref_fp32(weights, bank, state, x, ids, tw)
            torch.cuda.synchronize()
            m_rel = _combo_rel(master, ref)
            m_worst = max(m_worst, m_rel)
            ids_cpu = ids.cpu()
            lids_ref = _hm_local(ids, start, count)
            no_local = (lids_ref < 0).all(-1)
            m_zero = bool(no_local.any()) and float(master[no_local].abs().max()) == 0.0
            shape = _hm_counts_text(lids_ref, count)
            for h in HM_BSMS:
                if not ok[(tokens, h)]:
                    continue
                try:
                    ea["err"].zero_()
                    trace = _rt_tracer(HM_TAG, f"H={h} T={tokens} {label}") if first[h] else None
                    if trace:
                        print(f"{HM_TAG} first H={h} launch: T={tokens} {label} (each step synced)", flush=True)
                        trace("launching _hm_align")
                    lids, align = _hm_align(ids, state["hm"]["ls"], h, count)
                    if trace:
                        trace("_hm_align ok; launching _hm_experts (Marlin hot w13, silu_and_mul, Marlin w2"
                              + (", Engine A v3 cold w13 + w2" if h < 0 else "") + ", post-norm)")
                    out = _hm_experts(x, lids, tw.float().contiguous(), align, bank, state, h, fill=HM_JUNK).float()
                    torch.cuda.synchronize()
                    if trace:
                        trace("_hm_experts ok")
                    first[h] = False
                    problem = _hm_align_cmp(ids_cpu, start, h, count, lids, align)
                    errw = int(ea["err"][0])
                    if problem is None and errw != 0:
                        problem = f"Engine A error word {errw}"
                    if problem is None:
                        good, rel, row, text = _rt_check(out, ref)
                        worst[h] = max(worst[h], rel)
                        if not (good and rel <= 2.0 * max(m_rel, 2e-3)):
                            problem = f"{text}, master {m_rel:.3g} (<= 2x)"
                        elif m_zero and float(out[no_local].abs().max()) != 0.0:
                            problem = "a token without a local route is not exactly zero (master's is)"
                except Exception as e:  # prepare only
                    problem = f"raised {type(e).__name__}: {str(e)[:200]}"
                if problem is not None:
                    ok[(tokens, h)], why[(tokens, h)] = False, f"canary {label}: {problem}"
                    lines.append(f"{HM_TAG} canary FAIL H={h} T={tokens} {label} ({shape}): {problem}")
                    print(lines[-1], flush=True)
            print(f"{HM_TAG} canary T={tokens} {label}: {shape}; master vs fp32 {m_rel:.3g}", flush=True)
    for h in HM_BSMS:
        lines.append(f"{HM_TAG} canary H={h}: " + ", ".join(f"T={t} {'clean' if ok[(t, h)] else 'FAIL'}"
                                                            for t in HM_TOKENS)
                     + f"; worst rel-L2 vs fp32 {worst[h]:.3g} (master {m_worst:.3g})")
    return ok, why, lines


def _hm_gate(weights, bank, state, device, tokens, cands, seed):
    """kernel_fn as the judge times it at T = tokens: graphs of master (kernel_fn with this flag off) and of each
    candidate H on three reference-style draws (_ea_judge_routings: p10 / p50 / p90 by v3 passes), two interleaved
    cold-L2 rounds each (_rt_time). Returns ({routing label: rounds}, [routing lines])."""
    hm = state["hm"]
    start, count = bank["start"], bank["count"]
    hidden = weights["w2"].shape[1]
    gen = torch.Generator().manual_seed(seed)
    per, stats = {}, []
    try:
        for rlabel, ids in _ea_judge_routings(tokens, gen, start, count, device).items():
            tw = torch.rand((tokens, TOP_K), generator=gen)
            x = torch.randn((tokens, hidden), generator=gen).to(torch.bfloat16).to(device)
            data = _hm_data(bank, x, ids, (tw / tw.sum(-1, keepdim=True)).to(device))
            graphs = {}
            for name, h in (("master", 0),) + tuple((f"H{h}", h) for h in cands):
                hm["on"][tokens] = h
                graphs[name], _ = _rt_graph(lambda: kernel_fn(data, state))
            hm["on"][tokens] = 0
            label = f"T={tokens} {rlabel}"
            per[label] = _rt_time(graphs, device)
            stats.append(f"{HM_TAG} gate input {label}: " + _hm_counts_text(_hm_local(ids, start, count), count))
            print(stats[-1], flush=True)
            del graphs
    finally:
        hm["on"][tokens] = 0
    return per, stats


def _hm_layer_check(weights, bank, state, device, tokens, h):
    """kernel_fn with the flag at H vs off, eager, on two judge-like inputs (zipf, skewed-4hot): each against the fp32
    reference (_rt_check, <= 2x master's error). Covers the kernel_fn hook itself. Returns (problem or None, line)."""
    hm = state["hm"]
    start, count = bank["start"], bank["count"]
    hidden = weights["w2"].shape[1]
    gen = torch.Generator().manual_seed(20261102 + tokens)
    worst, m_worst = 0.0, 0.0
    try:
        routs = dict(_ea_routings(tokens, gen, list(range(start, start + count)), device))
        for label in ("zipf", "skewed-4hot"):
            ids = routs[label]
            x = torch.randn((tokens, hidden), generator=gen).to(torch.bfloat16).to(device)
            tw = torch.rand((tokens, TOP_K), generator=gen)
            tw = (tw / tw.sum(-1, keepdim=True)).to(device).contiguous()
            hm["on"][tokens] = 0
            master = kernel_fn(_hm_data(bank, x, ids, tw), state).float()
            hm["on"][tokens] = h
            got = kernel_fn(_hm_data(bank, x, ids, tw), state).float()
            hm["on"][tokens] = 0
            ref = _combo_ref_fp32(weights, bank, state, x, ids, tw)
            torch.cuda.synchronize()
            m_rel = _combo_rel(master, ref)
            good, rel, row, text = _rt_check(got, ref)
            worst, m_worst = max(worst, rel), max(m_worst, m_rel)
            if not (good and rel <= 2.0 * max(m_rel, 2e-3)):
                problem = f"layer check T={tokens} H={h} {label}: {text}, master {m_rel:.3g}"
                return problem, f"{HM_TAG} {problem} -> FAIL"
    finally:
        hm["on"][tokens] = 0
    return None, (f"{HM_TAG} layer check T={tokens} H={h} (kernel_fn hook, zipf + skewed-4hot vs fp32) ok: worst "
                  f"rel-L2 {worst:.3g} (master {m_worst:.3g})")


def _hm_copy_check(weights, bank, state, device):
    """The judge copies the prepared state (cloned tensors) and rotates the copies: per ON T, graphs of kernel_fn on
    this state and on a tensor-cloning copy (_wg_copy_tree), four replays alternating the order with refilled inputs,
    each against eager kernel_fn on this state. Returns (ok, line)."""
    on = state["hm"]["on"]
    start, count = bank["start"], bank["count"]
    hidden = weights["w2"].shape[1]
    local_set = list(range(start, start + count))
    ts = [t for t in HM_TOKENS if on.get(t, 0)]
    other = _wg_copy_tree(state)
    gen = torch.Generator().manual_seed(20261103)
    fails, n = [], 0
    for tokens in ts:
        per = []
        for st in (state, other):
            data = _hm_data(bank, torch.zeros((tokens, hidden), dtype=torch.bfloat16, device=device),
                            torch.full((tokens, TOP_K), start, dtype=torch.int32, device=device),
                            torch.full((tokens, TOP_K), 1.0 / TOP_K, dtype=torch.float32, device=device))
            graph, out = _rt_graph(lambda data=data, st=st: kernel_fn(data, st))
            per.append((data, graph, out))
        routs = dict(_ea_routings(tokens, gen, local_set, device))
        for k in range(4):
            ids = routs["zipf" if k % 2 == 0 else "skewed-4hot"]
            x = torch.randn((tokens, hidden), generator=gen).to(torch.bfloat16).to(device)
            tw = torch.rand((tokens, TOP_K), generator=gen).to(device)
            for data, _, _ in per:
                data["hidden_states"].copy_(x)
                data["topk_ids"].copy_(ids)
                data["topk_weights"].copy_(tw)
            for _, graph, _ in (per if k % 2 == 0 else per[::-1]):
                graph.replay()
            torch.cuda.synchronize()
            ref = kernel_fn(_hm_data(bank, x, ids, tw), state).float()
            torch.cuda.synchronize()
            for i, (_, _, out) in enumerate(per):
                n += 1
                rel = _combo_rel(out.float(), ref)
                if not rel <= HM_COPY_TOL:
                    fails.append(f"T={tokens} (H={on[tokens]}) state {'AB'[i]} refill {k}: rel-L2 vs eager {rel:.3g}")
        del per
        torch.cuda.synchronize()
    del other
    gc.collect()
    torch.cuda.empty_cache()
    return not fails, (f"{HM_TAG} copy check: {n} replays on two states, T {ts}: "
                       + ("PASS" if not fails else f"FAIL -> master for every T: {fails[0]}"))


def _hm_path_lines(state, why, times):
    """One PATH CHOSEN line per T, read from the state's flags (what kernel_fn runs)."""
    out = []
    for t in HM_TOKENS:
        h = state["hm"]["on"].get(t, 0)
        tm = times.get(t, {})
        ttxt = "; ".join(f"{r}: " + ", ".join(f"{n} {v:.1f}" for n, v in d.items()) for r, d in tm.items())
        if h:
            kind = "HYBRID (hot on Marlin, cold on Engine A v3)" if h < 0 else "HOT/COLD (both on Marlin, cold block 16)"
            out.append(f"{HM_TAG} PATH CHOSEN T={t} = {kind} H={h} (hot > {_hm_hot_rows(h)} rows at block {_hm_hot_block(h)}); "
                       f"layer us {ttxt}")
        else:
            out.append(f"{HM_TAG} PATH CHOSEN T={t} = MASTER (fallback: {why.get(t, 'off')}"
                       + (f"; layer us {ttxt}" if ttxt else "") + ")")
    return out


def _hm_setup(weights, state, device, t_prepare):
    """After Engine A's setup (prepare() only). Never raises: any miss leaves state['hm']['on'][T] = 0 (kernel_fn's
    existing path). Detail lines print as they happen; the return value is the compact summary for prepare() to print
    last, with the PATH CHOSEN lines at the end."""
    t0 = time.perf_counter()
    state["hm"] = {"on": {t: 0 for t in HM_TOKENS}}
    on = state["hm"]["on"]
    why, times, notes = {}, {}, []

    def late(limit):
        return time.perf_counter() - t_prepare > limit

    def say(line):
        print(line, flush=True)
        notes.append(line)

    try:
        if late(HM_START_DEADLINE_S):
            raise RuntimeError(f"skipped: deadline (start at {time.perf_counter() - t_prepare:.1f} s)")
        bank = state["banks"][(0, 32)]
        ea = state.get("ea") or {}
        if not (ea.get("ext") is not None and "v3" not in ea.get("skip", ()) and "w13r" in ea):
            raise RuntimeError("Engine A v3 not built in this prepare (state['ea'])")
        if (bank["expert_map"] is None or bank["count"] != 32 or bank["size_n"] != 4096
                or weights["w2"].shape[1] != 4096):
            raise RuntimeError(f"unsupported bank: count {bank['count']}, size_n {bank['size_n']}")
        # expert-bandwidth: kernel_fn takes this hook before Engine A, so the gate below times H against Engine A's
        # (or the wg / Marlin path's) choice for T; the cold half runs on v4 when it is built.
        state["hm"]["cold"] = "v4" if ("v4" in EA_ENGINES and "v4" not in ea.get("skip", ())
                                       and hasattr(ea["ext"], "ea4_w13")) else "v3"
        # v4c: the cold half takes Engine A's split for the T (cost-weighted when its gate chose v4c)
        state["hm"]["cold_bits"] = {t: (EA_PDL_BITS.get(ea.get("on", {}).get(t), 0) if state["hm"]["cold"] == "v4"
                                        else 0) for t in HM_TOKENS}
        state["hm"]["ls"] = torch.tensor([bank["start"]], dtype=torch.int32, device=device)
        built, wlines = _hm_warm(device, state, bank["count"])
        if state.get("wg_ext") is None or (bank["start"], bank["count"]) not in state.get("wg_banks", {}):
            for hw in HM_WG_HOT:
                built[hw] = "the wgmma path is not built in this prepare"
        for ln in wlines:
            say(ln)
        ok, kwhy, klines = _hm_canary(weights, bank, state, device, t_prepare, built)
        for ln in klines:
            if "FAIL H=" not in ln:  # the FAIL lines printed as they happened
                print(ln, flush=True)
            notes.append(ln)
        for tokens in HM_TOKENS:
            cands = [h for h in HM_BSMS if ok.get((tokens, h), False)]
            if not cands:
                why[tokens] = ("; ".join(sorted({kwhy[(tokens, h)] for h in HM_BSMS if (tokens, h) in kwhy}))[:300]
                               or "no clean H")
                continue
            if late(HM_GATE_DEADLINE_S):
                why[tokens] = "gate skipped: deadline"
                continue
            try:
                per, stats = _hm_gate(weights, bank, state, device, tokens, cands, 20261104 + tokens)
                notes.extend(stats)
                win, worst, glines = _rt_select(per, "master", [f"H{h}" for h in cands])
                for ln in glines:
                    print(f"{HM_TAG} gate {ln}", flush=True)
                times[tokens] = {lab.split()[-1]: {name: sum(_rt_stats(r[name])[0] for r in rounds) / len(rounds)
                                                   for name in ["master"] + [f"H{h}" for h in cands]}
                                 for lab, rounds in per.items()}
                say(f"{HM_TAG} gate T={tokens} (kernel_fn graphs, zipf + random x 2 rounds): worst ratio "
                    + ", ".join(f"H{h} x{worst[f'H{h}']:.3f}" for h in cands)
                    + f" -> {win if win else 'master'}")
                if win is None:
                    why[tokens] = "no H wins every round (" + ", ".join(f"H{h} x{worst[f'H{h}']:.3f}" for h in cands) + ")"
                    continue
                h = int(win[1:])
                if late(HM_COPY_DEADLINE_S):
                    why[tokens] = "layer check skipped: deadline"
                    continue
                problem, line = _hm_layer_check(weights, bank, state, device, tokens, h)
                say(line)
                if problem is not None:
                    why[tokens] = "layer check FAIL"
                    continue
                on[tokens] = h
            except Exception as e:
                on[tokens] = 0
                why[tokens] = f"gate {type(e).__name__}"
                say(f"{HM_TAG} T={tokens} raised {type(e).__name__}: {str(e)[:300]}")
        if any(on.values()):
            if late(HM_COPY_DEADLINE_S):
                for t in HM_TOKENS:
                    if on[t]:
                        on[t], why[t] = 0, "copy check skipped: deadline"
                say(f"{HM_TAG} copy check: skipped: deadline -> master for every T")
            else:
                cok, line = _hm_copy_check(weights, bank, state, device)
                say(line)
                if not cok:
                    for t in HM_TOKENS:
                        if on[t]:
                            on[t], why[t] = 0, "copy check FAIL"
    except Exception as e:  # prepare only: never raises, every T keeps master
        for t in HM_TOKENS:
            on[t] = 0
            why.setdefault(t, type(e).__name__)
        say(f"{HM_TAG} {type(e).__name__}: {str(e)[:400]}")
    try:
        torch.cuda.synchronize()
    except Exception as e:
        say(f"{HM_TAG} final sync raised {type(e).__name__}: {str(e)[:200]}")
    tail = [f"{HM_TAG} ===== MOE HYBRID (T {HM_TOKENS}) SUMMARY ({time.perf_counter() - t0:.1f} s; prepare at "
            f"{time.perf_counter() - t_prepare:.1f} s) ====="]
    tail.extend(notes)
    try:
        tail.extend(_hm_path_lines(state, why, times))
    except Exception as e:  # never raise from prepare: master everywhere
        for t in HM_TOKENS:
            on[t] = 0
        tail.append(f"{HM_TAG} PATH CHOSEN T={HM_TOKENS} = MASTER (summary raised {type(e).__name__}: {str(e)[:200]})")
    return tail
